#include <stdio.h>
#include <string.h>

int main(void) {
    const char *s = "xxababacaxx", *p = "ababaca";
    int n = (int)strlen(s), m = (int)strlen(p), next[16];
    next[0] = 0;
    for (int i = 1, len = 0; i < m; ) {
        if (p[i] == p[len]) next[i++] = ++len;
        else if (len > 0)   len = next[len - 1];
        else                next[i++] = 0;
    }
    int pos = -1, j = 0;
    for (int i = 0; i < n; i++) {              /* i 只增不减 */
        while (j > 0 && s[i] != p[j]) j = next[j - 1];
        if (s[i] == p[j]) j++;
        if (j == m) { pos = i - m + 1; break; }
    }
    printf("主串: %s\n", s);
    printf("模式: %s\n", p);
    printf("首次匹配位置: %d\n", pos);
    return 0;
}
